adcs_quat_t qm, qp, q_rel;
adcs_vec3_t vec;
double vec_norm;

if ((predicted == NULL) || (measured == NULL) || (rotation_vector == NULL) || (angle == NULL)) {
    if (rotation_vector != NULL) {
        rotation_vector->x = 0.0;
        rotation_vector->y = 0.0;
        rotation_vector->z = 0.0;
    }
    if (angle != NULL) {
        *angle = INFINITY;
    }
    return ADCS_E_NULL;
}

rotation_vector->x = 0.0;
rotation_vector->y = 0.0;
rotation_vector->z = 0.0;
*angle = INFINITY;

if (adcs_quat_normalize(measured, &qm) != ADCS_OK ||
    adcs_quat_normalize(predicted, &qp) != ADCS_OK) {
    return ADCS_E_DEGENERATE;
}

q_rel = adcs_quat_multiply(&qm, &adcs_quat_conjugate(&qp));

if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

*angle = 2.0 * acos(ADCS_CLAMP(q_rel.w, 0.0, 1.0));

vec.x = q_rel.x;
vec.y = q_rel.y;
vec.z = q_rel.z;
vec_norm = adcs_vec3_norm(&vec);

if (vec_norm <= ADCS_EPS_NORM) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
} else {
    rotation_vector->x = *angle * vec.x / vec_norm;
    rotation_vector->y = *angle * vec.y / vec_norm;
    rotation_vector->z = *angle * vec.z / vec_norm;
}

return ADCS_OK;

